function fixInst(inst){
  const v = inst.children[0];
  if (!v || v.type!=="VECTOR") return;
  let color = {r:0.102,g:0.102,b:0.122};
  if (inst.fills && inst.fills.length && inst.fills[0].type==="SOLID") color = inst.fills[0].color;
  inst.fills = [];
  v.fills = [{type:"SOLID", color}];
}
